entries[19775] = { ["name"] = "Dunkle Besserung", ["text"] = "500 Mana Unbegrenzte Reichweite\nWirken in 2.5 sek.\nHeilt bei einem Verbündeten 27750 bis 32250 Punkt(e) Schaden unter Verwendung von dunkler Magie." }
entries[19776] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "95 Mana 30 Meter Reichweite\nSofort\nMurmelt ein Wort der Dunkelheit, das einem Feind 18 Sek. lang alle 3 Sek. Schattenschaden zufügt." }
entries[19777] = { ["name"] = "Dunkler Stoß", ["text"] = "250 Mana 10 Meter Reichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nWeiht die Waffe des Zaubernden und verursacht bei ihrem nächsten Angriff 570 bis 630 Punkt(e) zusätzlichen Schaden. Der gesamte zugefügte Schaden wird als Schattenschaden angesehen." }
entries[19778] = { ["name"] = "Demoralisierender Ruf", ["text"] = "Sofort\nVerringert Nahkampf- und Distanzangriffskraft von in der Nähe befindlichen Feinden 30 Sek. lang um 300." }
entries[19779] = { ["name"] = "Inspirieren", ["text"] = "Unbegrenzte Reichweite\nSofort\nErhöht den von einem Verbündeten zugefügten körperlichen Schaden um 25% und sein Angriffstempo 10 Sek. lang um 100%." }
entries[19780] = { ["name"] = "Hand von Ragnaros", ["text"] = "Sofort\nFügt in der Nähe befindlichen Feinden 300 bis 400 Punkt(e) Feuerschaden zu, stößt sie zurück und betäubt sie 2 Sek. lang." }
entries[19781] = { ["name"] = "Flammenspeer", ["text"] = "45 Meter Reichweite\nSofort\nWirft einen Flammenspeer, verursacht bei einem Feind 850 bis 1150 Punkt(e) Feuerschaden und versengt außerdem alle anderen Feinde in der Nähe des Ziels." }
entries[19784] = { ["name"] = "Dunkeleisenbombe", ["text"] = "15 Meter Reichweite\nWirken in 1 sek.\nFügt 225 bis 675 Feuerschaden zu und betäubt Ziele 4 Sek. lang in einem Umkreis von 5 Metern. Jeglicher Schaden wird den Effekt abbrechen." }
entries[19785] = { ["name"] = "Werfen", ["text"] = "8 - 40 Meter Reichweite\nSofort\nWirft eine Waffe nach einem Feind und fügt 2125 bis 2875 Punkt(e) Schaden zu." }
entries[19786] = { ["name"] = "Stille widerstehen", ["text"] = "Erhöht Euren Widerstand gegen Stilleeffekte um 7%." }
entries[19787] = { ["name"] = "Rüstung erhöht 110", ["text"] = "+110 Rüstung." }
entries[19788] = { ["name"] = "Dichtes Sprengpulver", ["text"] = "Wirken in 8 sek.\nReagenzien:\nVerdichteter Stein (2)" }
entries[19790] = { ["name"] = "Thoriumgranate", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumapparat , Thoriumbarren (3), Dichtes Sprengpulver (3), Runenstoff (3)\n(3)\nBenötigtIngenieurskunst\n(260)\nBenutzen: Fügt 300 bis 500 Feuerschaden zu und betäubt Ziele 3 Sek. lang in einem Umkreis von 3 Metern. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)" }
entries[19791] = { ["name"] = "Thoriumapparat", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nThoriumbarren (3), Runenstoff" }
entries[19792] = { ["name"] = "Thoriumgewehr", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr (2), Mithrilgehäuse (2), Thoriumapparat (2), Thoriumbarren (4), Tödliches Zielfernrohr\nThoriumgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n42 - 79 Schaden Tempo 2.50\n(24.20 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\n47\nAnlegen: +17 Distanzangriffskraft." }
entries[19793] = { ["name"] = "Lebensechte mechanische Kröte", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nEssenz des Lebens , Thoriumapparat (4), Goldkraftkern , Unverwüstliches Leder\nWird bei Benutzung gebunden\nBenutzen: Mit Rechtsklick Eure lebensechte mechanische Kröte beschwören und freigeben." }
entries[19794] = { ["name"] = "Zaubermachtschutzbrille Xtrem Plus", ["text"] = "Wirken in 45 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nZaubermachtschutzbrille Xtrem , Sternrubin (4), Verzaubertes Leder (2), Runenstoff (8)\nZaubermachtschutzbrille Xtrem Plus\nWird beim Anlegen gebunden\nKopf Stoff\n57 Rüstung\nHaltbarkeit 45 / 45\nBenötigtIngenieurskunst\n(270)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 27." }
entries[19795] = { ["name"] = "Thoriumröhre", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nThoriumbarren (6)" }
entries[19796] = { ["name"] = "Dunkeleisengewehr", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nThoriumröhre (2), Dunkeleisenbarren (6), Tödliches Zielfernrohr (2), Blauer Saphir (2), Großer Opal (2), Unverwüstliches Leder (4)\nDunkeleisengewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n53 - 100 Schaden Tempo 2.70\n(28.33 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\n50\nAnlegen: Gewährt eine Chance, Euer Distanzziel mit einem Schattenschuss zu treffen und 18 bis 26 Schattenschaden zu verursachen." }
