entries[19798] = { ["name"] = "Erdbeben", ["text"] = "Sofort\nVerursacht bei in der Nähe befindlichen Feinden 1388 bis 1612 Punkt(e) Schaden." }
entries[19799] = { ["name"] = "Dunkeleisenbombe", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumapparat (2), Dunkeleisenbarren , Dichtes Sprengpulver (3), Runenstoff (3)\n(3)\nBenötigtIngenieurskunst\n(285)\nBenutzen: Fügt 225 bis 675 Feuerschaden zu und betäubt Ziele 4 Sek. lang in einem Umkreis von 5 Metern. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)" }
entries[19800] = { ["name"] = "Thoriumpatronen", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (2), Dichtes Sprengpulver\nThoriumpatronen\n(200)Munition Kugel\nVerursacht 17.5 zusätzlichen Schaden pro Sekunde.\n52" }
